if($_SERVER['REQUEST_METHOD']==='POST'){
    try{csrf_verify();$action=$_POST['save_action']??'open';$vendorId=(int)($_POST['vendor_id']??0);$invoiceNumber=trim($_POST['invoice_number']??'');$invoiceDate=$_POST['invoice_date']??date('Y-m-d');$dueDate=$_POST['due_date']??$invoiceDate;$paymentTerms=trim($_POST['payment_terms']??'');$place=trim($_POST['place_of_supply']??'Dubai');$vatTreatment=$_POST['vat_treatment']??'vat_registered';$orderNo=trim($_POST['order_number']??'');$permitNo=trim($_POST['permit_number']??'');$notes=trim($_POST['notes']??'');$items=$_POST['items']??[]; if(!$vendorId||$invoiceNumber==='')throw new RuntimeException('Vendor and Bill # are required.');$valid=[];$subtotal=0;$vat=0;$total=0;foreach($items as $it){$acct=(int)($it['expense_account_id']??0);$desc=trim($it['description']??'');$qty=(float)($it['quantity']??1);$rate=(float)($it['unit_price']??0);$vr=(float)($it['vat_rate']??0);$vt=$it['vat_treatment']??'standard';if($acct<=0||$qty<=0||$rate<0)continue;$lineSub=round($qty*$rate,2);$lineVat=($vt==='standard'&&$vr>0)?round($lineSub*$vr/100,2):0;$lineTotal=$lineSub+$lineVat;$valid[]=['expense_account_id'=>$acct,'description'=>$desc,'quantity'=>$qty,'unit_price'=>$rate,'subtotal'=>$lineSub,'vat_treatment'=>$vt,'vat_rate'=>$vr,'vat_amount'=>$lineVat,'line_total'=>$lineTotal,'building_id'=>(int)($it['building_id']??0),'unit_id'=>(int)($it['unit_id']??0),'lease_id'=>(int)($it['lease_id']??0)];$subtotal+=$lineSub;$vat+=$lineVat;$total+=$lineTotal;}if(!$valid)throw new RuntimeException('Add at least one valid line with expense account.');$status=$action==='draft'?'draft':'open';$conn->beginTransaction();$stmt=$conn->prepare("INSERT INTO re_vendor_invoices (company_id,vendor_id,invoice_number,order_number,permit_number,place_of_supply,vat_treatment,invoice_date,due_date,payment_terms,subtotal,tax_amount,discount_amount,total_amount,paid_amount,balance_due,status,posting_status,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,0,?,?,?,?,'not_posted',?,?)");$stmt->execute([$companyId,$vendorId,$invoiceNumber,$orderNo?:null,$permitNo?:null,$place?:'Dubai',$vatTreatment,$invoiceDate,$dueDate,$paymentTerms?:null,round($subtotal,2),round($vat,2),round($total,2),0,round($total,2),$status,$notes?:null,$userId]);$billId=(int)$conn->lastInsertId();$lineStmt=$conn->prepare("INSERT INTO re_vendor_invoice_items (company_id,invoice_id,expense_account_id,building_id,unit_id,lease_id,service_name,description,line_description,quantity,unit_price,subtotal,vat_treatment,vat_rate,vat_amount,line_total,total_price) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");foreach($valid as $ln){$lineStmt->execute([$companyId,$billId,$ln['expense_account_id'],$ln['building_id']?:null,$ln['unit_id']?:null,$ln['lease_id']?:null,$ln['description']?:'Bill line',$ln['description']?:null,$ln['description']?:null,$ln['quantity'],$ln['unit_price'],$ln['subtotal'],$ln['vat_treatment'],$ln['vat_rate'],$ln['vat_amount'],$ln['line_total'],$ln['line_total']]);}
    if(!empty($_FILES['attachments']['name'][0])){ $dir=__DIR__.'/../../../uploads/vendor_bills'; if(!is_dir($dir))mkdir($dir,0755,true); foreach($_FILES['attachments']['name'] as $i=>$name){ if($_FILES['attachments']['error'][$i]!==UPLOAD_ERR_OK)continue; $ext=strtolower(pathinfo($name,PATHINFO_EXTENSION)); if(!in_array($ext,['pdf','png','jpg','jpeg','webp','xls','xlsx','doc','docx'],true))continue; $safe='bill_'.$billId.'_'.time().'_'.$i.'.'.$ext; $path=$dir.'/'.$safe; if(move_uploaded_file($_FILES['attachments']['tmp_name'][$i],$path)){ $rel='uploads/vendor_bills/'.$safe; $conn->prepare("INSERT INTO re_vendor_bill_attachments (company_id,vendor_invoice_id,file_name,file_path,mime_type,file_size,uploaded_by) VALUES (?,?,?,?,?,?,?)")->execute([$companyId,$billId,$name,$rel,$_FILES['attachments']['type'][$i]??null,$_FILES['attachments']['size'][$i]??null,$userId]); } } }
    if($action==='open'){ $post=re_ap_post_vendor_bill($conn,$companyId,$billId,$userId); if(empty($post['success']))throw new RuntimeException('Bill saved but posting failed: '.$post['error']); }
    re_ap_audit($conn,$companyId,$vendorId,$billId,null,'bill_created',null,$status,$total,'Vendor bill created',$userId,'bill_entry');$conn->commit();$success='Vendor bill saved.'.($action==='open'?' Posted to AP.':'');}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();$error=$e->getMessage();}}
