"form-label">Attachments</label><input type="file" name="attachments[]" class="form-control" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.xls,.xlsx,.doc,.docx"></div></div><hr><h6>Line Items</h6><div class="table-responsive"><table class="table table-sm" id="billLines"><thead><tr><th>Description</th><th>Expense Account</th><th>Qty</th><th>Rate</th><th>VAT</th><th>Building</th><th>Lease</th><th class="text-end">Total</th><th></th></tr></thead><tbody></tbody></table></div><button type="button" class="btn btn-sm btn-outline-primary" id="addLine">Add Line</button><div class="text-end mt-3"><div>Subtotal: <strong id="subtotal">0.00</strong></div><div>VAT: <strong id="vatTotal">0.00</strong></div><div>Total: <strong id="grandTotal">0.00</strong> AED</div></div><hr><button name="save_action" value="draft" class="btn btn-outline-secondary">Save as Draft</button> <button name="save_action" value="open" class="btn btn-primary">Save as Open / Post</button></div></form>
<script>
const accounts=<?=json_encode($accounts)?>, buildings=<?=json_encode($buildings)?>, leases=<?=json_encode($leases)?>;let idx=0;function opt(list,val,label){return list.map(x=>`<option value="${x[val]}">${x[label]}</option>`).join('')}function addLine(){const tr=document.createElement('tr');tr.innerHTML=`<td><input name="items[${idx}][description]" class="form-control form-control-sm" required></td><td><select name="items[${idx}][expense_account_id]" class="form-select form-select-sm" required><option value="">-- Account --</option>${accounts.map(a=>`<option value="${a.id}">${a.account_code} ${a.account_name}</option>`).join('')}</select></td><td><input type="number" step="0.01" name="items[${idx}][quantity]" class="form-control form-control-sm qty" value="1"></td><td><input type="number" step="0.01" name="items[${idx}][unit_price]" class="form-control form-control-sm rate" value="0"></td><td><select name="items[${idx}][vat_treatment]" class="form-select form-select-sm"><option value="standard">5%</option><option value="exempt">Exempt</option><option value="zero_rated">Zero</option><option value="out_of_scope">OOS</option></select><input type="hidden" name="items[${idx}][vat_rate]" value="5"></td><td><select name="items[${idx}][building_id]" class="form-select form-select-sm"><option value="">-</option>${opt(buildings,'id','name')}</select></td><td><select name="items[${idx}][lease_id]" class="form-select form-select-sm"><option value="">-</option>${leases.map(l=>`<option value="${l.id}">${l.lease_number} - ${l.building_name} ${l.unit_number}</option>`).join('')}</select></td><td class="text-end lineTotal">0.00</td><td><button type="button" class="btn btn-sm btn-danger rem">x</button></td>`;document.querySelector('#billLines tbody').appendChild(tr);idx++;calc()}function calc(){let sub=0,vat=0;document.querySelectorAll('#billLines tbody tr').forEach(tr=>{let q=parseFloat(tr.querySelector('.qty').value)||0,r=parseFloat(tr.querySelector('.rate').value)||0,vt=tr.querySelector('select[name*="vat_treatment"]').value;let s=q*r,v=vt==='standard'?s*.05:0;tr.querySelector('input[name*="vat_rate"]').value=vt==='standard'?5:0;tr.querySelector('.lineTotal').textContent=(s+v).toFixed(2);sub+=s;vat+=v;});document.getElementById('subtotal').textContent=sub.toFixed(2);document.getElementById('vatTotal').textContent=vat.toFixed(2);document.getElementById('grandTotal').textContent=(sub+vat).toFixed(2)}document.getElementById('addLine').onclick=addLine;document.getElementById('billLines').addEventListener('input',calc);document.getElementById('billLines').addEventListener('change',calc);document.getElementById('billLines').addEventListener('click',e=>{if(e.target.classList.contains('rem')){e.target.closest('tr').remove();calc();}});addLine();
</script>
